package solution

import (
	"math"
	"testing"
)

func closeFloat(a, b float64) bool {
	return math.Abs(a-b) <= 1e-9
}

func assertFrameClose(t *testing.T, got, want Frame) {
	t.Helper()
	if !closeFloat(got.East, want.East) ||
		!closeFloat(got.North, want.North) ||
		!closeFloat(got.Up, want.Up) ||
		!closeFloat(got.Azimuth, want.Azimuth) ||
		!closeFloat(got.Elevation, want.Elevation) {
		t.Fatalf("frame = %+v, want %+v", got, want)
	}
}

func TestAdvanceCardinalVerticalAndBackward(t *testing.T) {
	tests := []struct {
		name     string
		frame    Frame
		distance float64
		want     Frame
	}{
		{"north", Frame{East: 1, North: 2, Up: 3, Azimuth: 0}, 4, Frame{East: 1, North: 6, Up: 3, Azimuth: 0}},
		{"east", Frame{Azimuth: 90}, 5, Frame{East: 5, Azimuth: 90}},
		{"backward west", Frame{East: 10, North: 2, Up: 1, Azimuth: 90}, -3, Frame{East: 7, North: 2, Up: 1, Azimuth: 90}},
		{"straight up", Frame{East: 4, North: 5, Up: 6, Azimuth: 123, Elevation: 90}, 2, Frame{East: 4, North: 5, Up: 8, Azimuth: 123, Elevation: 90}},
		{"downward", Frame{Up: 3, Azimuth: 0, Elevation: -30}, 2, Frame{North: math.Sqrt(3), Up: 2, Azimuth: 0, Elevation: -30}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			original := tc.frame
			got, err := Advance(tc.frame, tc.distance)
			if err != nil {
				t.Fatalf("Advance failed: %v", err)
			}
			assertFrameClose(t, got, tc.want)
			if tc.frame != original {
				t.Fatalf("Advance mutated input value: got %+v, want %+v", tc.frame, original)
			}
		})
	}
}

func TestAdvanceNormalizesAzimuthIncludingZeroDistance(t *testing.T) {
	frame := Frame{East: 1, North: 2, Up: 3, Azimuth: -450, Elevation: 10}
	got, err := Advance(frame, 0)
	if err != nil {
		t.Fatalf("Advance failed: %v", err)
	}
	want := frame
	want.Azimuth = 270
	assertFrameClose(t, got, want)

	frame.Azimuth = 720
	got, err = Advance(frame, 1)
	if err != nil {
		t.Fatalf("Advance failed: %v", err)
	}
	want = Frame{
		East:      1,
		North:     2 + math.Cos(10*math.Pi/180),
		Up:        3 + math.Sin(10*math.Pi/180),
		Azimuth:   0,
		Elevation: 10,
	}
	assertFrameClose(t, got, want)
}

func TestReorientNormalizesAndClamps(t *testing.T) {
	tests := []struct {
		frame Frame
		dAz   float64
		dEl   float64
		want  Frame
	}{
		{Frame{East: 1, North: 2, Up: 3, Azimuth: 350, Elevation: 80}, 20, 30, Frame{East: 1, North: 2, Up: 3, Azimuth: 10, Elevation: 90}},
		{Frame{Azimuth: 10, Elevation: -80}, -40, -50, Frame{Azimuth: 330, Elevation: -90}},
		{Frame{Azimuth: 720, Elevation: 4}, 0, 0, Frame{Azimuth: 0, Elevation: 4}},
		{Frame{Azimuth: -1, Elevation: 90}, 721, -180, Frame{Azimuth: 0, Elevation: -90}},
	}
	for _, tc := range tests {
		original := tc.frame
		got, err := Reorient(tc.frame, tc.dAz, tc.dEl)
		if err != nil {
			t.Fatalf("Reorient(%+v, %v, %v) failed: %v", tc.frame, tc.dAz, tc.dEl, err)
		}
		assertFrameClose(t, got, tc.want)
		if tc.frame != original {
			t.Fatalf("Reorient mutated input value: got %+v, want %+v", tc.frame, original)
		}
	}
}

func TestMalformedInputsReturnOriginalFrame(t *testing.T) {
	base := Frame{East: 1, North: 2, Up: 3, Azimuth: 4, Elevation: 5}
	badFrames := []Frame{
		{East: math.NaN(), North: 2, Up: 3, Azimuth: 4, Elevation: 5},
		{East: 1, North: math.Inf(1), Up: 3, Azimuth: 4, Elevation: 5},
		{East: 1, North: 2, Up: math.Inf(-1), Azimuth: 4, Elevation: 5},
		{East: 1, North: 2, Up: 3, Azimuth: math.NaN(), Elevation: 5},
		{East: 1, North: 2, Up: 3, Azimuth: 4, Elevation: 90.0001},
		{East: 1, North: 2, Up: 3, Azimuth: 4, Elevation: -90.0001},
	}
	for _, frame := range badFrames {
		got, err := Advance(frame, 1)
		if err == nil {
			t.Fatalf("Advance accepted malformed frame %+v", frame)
		}
		assertSameMalformedFrame(t, got, frame)

		got, err = Reorient(frame, 1, 1)
		if err == nil {
			t.Fatalf("Reorient accepted malformed frame %+v", frame)
		}
		assertSameMalformedFrame(t, got, frame)
	}

	for _, distance := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
		got, err := Advance(base, distance)
		if err == nil || got != base {
			t.Fatalf("Advance with malformed distance returned (%+v, %v), want original and error", got, err)
		}
	}
	badDeltas := [][2]float64{
		{math.NaN(), 0}, {math.Inf(1), 0}, {math.Inf(-1), 0},
		{0, math.NaN()}, {0, math.Inf(1)}, {0, math.Inf(-1)},
	}
	for _, deltas := range badDeltas {
		got, err := Reorient(base, deltas[0], deltas[1])
		if err == nil || got != base {
			t.Fatalf("Reorient with malformed deltas returned (%+v, %v), want original and error", got, err)
		}
	}
}

func assertSameMalformedFrame(t *testing.T, got, want Frame) {
	t.Helper()
	fieldsGot := []float64{got.East, got.North, got.Up, got.Azimuth, got.Elevation}
	fieldsWant := []float64{want.East, want.North, want.Up, want.Azimuth, want.Elevation}
	for i := range fieldsGot {
		if math.IsNaN(fieldsWant[i]) {
			if !math.IsNaN(fieldsGot[i]) {
				t.Fatalf("field %d = %v, want NaN", i, fieldsGot[i])
			}
		} else if fieldsGot[i] != fieldsWant[i] {
			t.Fatalf("malformed result changed field %d: got %v, want %v", i, fieldsGot[i], fieldsWant[i])
		}
	}
}

package solution

import (
	"math"
	"testing"
)

func TestReviewFiniteAngles(t *testing.T) {
	frame := Frame{East: 1, North: 2, Up: 3, Azimuth: math.MaxFloat64}
	got, err := Advance(frame, 0)
	if err != nil || got.East != frame.East || got.North != frame.North || got.Up != frame.Up || math.IsNaN(got.Azimuth) || got.Azimuth < 0 || got.Azimuth >= 360 {
		t.Errorf("zero distance with finite azimuth: got %+v, err %v", got, err)
	}
	got, err = Reorient(frame, math.MaxFloat64, 0)
	if err != nil || math.IsNaN(got.Azimuth) || math.IsInf(got.Azimuth, 0) || got.Azimuth < 0 || got.Azimuth >= 360 {
		t.Errorf("finite angle sum must normalize: got %+v, err %v", got, err)
	}
}

